<fieldset class="fieldset"><legend>Permissions</legend><div class="checkbox-grid">@foreach (['read' => ['Read', 'Download objects'], 'write' => ['Write', 'Upload and copy files'], 'list' => ['List', 'Browse buckets and keys'], 'delete' => ['Delete', 'Remove stored objects']] as $scope => $description)<label class="checkbox-choice" for="{{ $identifier }}-scope-{{ $scope }}"><input id="{{ $identifier }}-scope-{{ $scope }}" name="scopes[]" type="checkbox" value="{{ $scope }}" @checked(in_array($scope, $selectedScopes, true) || in_array('*', $selectedScopes, true))><span>{{ $description[0] }}<small>{{ $description[1] }}</small></span></label>@endforeach</div></fieldset>
<fieldset class="fieldset"><legend>Bucket access</legend><p class="field-hint">Select specific buckets, or leave all clear to allow every bucket.</p>@if ($bucketRows->isNotEmpty())<div class="checkbox-grid">@foreach ($bucketRows as $bucket)<label class="checkbox-choice" for="{{ $identifier }}-bucket-{{ $bucket->id }}"><input id="{{ $identifier }}-bucket-{{ $bucket->id }}" type="checkbox" name="bucket_names[]" value="{{ $bucket->name }}" @checked(in_array($bucket->name, $selectedBuckets, true))><x-console-icon name="bucket" /><span>{{ $bucket->name }}</span></label>@endforeach</div>@else<p class="field-hint">No buckets yet. This key will apply to buckets you create later.</p>@endif</fieldset>
